  const W_NAU = (time, extra = {}) => ({ bg: 'espai', sprites: [{ id: 'nau', art: 'nau', x: 0, y: -120 }, { id: 'meteorit', art: 'meteorit', x: 0, y: 150, prog: METEOR }], vars: ['vides'], time, ...extra });
  const GANA = '@mascota flag{ setv:gana,0 forever{ wait:1 chv:gana,1 } }';
  const PET = (prog) => [{ id: 'mascota', art: 'mascota', x: 0, y: -30, size: 130, prog }, { id: 'poma', art: 'poma', x: -170, y: -120, size: 120, name: 'Poma (menjar)|Manzana (comida)' }, { id: 'pilota', art: 'pilota', x: 170, y: -120, size: 120 }];
  const PET_FULL = '@mascota flag{ setv:gana,0 forever{ wait:1 chv:gana,1 } } flag{ setv:alegria,5 forever{ wait:1.5 chv:alegria,-1 } } flag{ forever{ if:$gana>5{ costume:2 } else{ if:$alegria<3{ costume:4 } else{ costume:1 } } } } click{ say:$gana,1 } @poma click{ chv:gana,-3 sound:pop } @pilota click{ chv:alegria,2 sound:boing }';
