        w: { bg: 'parc', sprites: PET(GANA), vars: ['gana'], input: [{ t: 4.2, click: 'poma' }], time: 5.5, goal: [{ k: 'var', v: 'gana', eq: 2 }, { k: 'running', t: 5.4 }] },
        edit: ['poma'], hats: ['click'], pal: ['chv', 'setv', 'sound', 'say', 'size', 'chsize'], varNames: VN,
