        edit: ['mascota', 'poma', 'pilota'], hats: ['flag', 'click'], pal: ['setv', 'chv', 'forever', 'wait', 'if', 'else', 'cond+', 'costume', 'next', 'say', 'think', 'sound', 'chsize', 'size', 'turn', 'chy', 'rep'], varNames: VN,
        texts: ['Ñam!|¡Ñam!', 'Tinc gana!|¡Tengo hambre!', 'Quina alegria!|¡Qué alegría!'],
        prog: '@mascota flag{ } flag{ forever{ if:$gana>5{ } else{ } } }',
